import { styled, View } from '@tamagui/web';

import type { TabsContract } from './Tabs.contract';
import { TabsContext, tabsValue } from './TabsContext';
import { ariaAndDataAttributes } from '../../helpers/ariaAndDataAttributes';
import { pickWebPressHandlers } from '../../helpers/pickWebPressHandlers';
import { prependClassName } from '../../helpers/prependClassName';
import type { WebDivPressAlias, WebDivProps } from '../../types/WebAttributes';

export type TabsProps = WebDivProps<TabsContract> & WebDivPressAlias;

// generated by scripts/generate-frame-values.mts from @rocket.chat/fuselage-tokens, do not edit

const tabsFrame = {
	render: 'div',
	display: 'flex',
	flexDirection: 'row',
	alignItems: 'normal',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	position: 'relative',
} as const;

const tabsDividers = {
	with: {
		borderBottomWidth: 1,
		borderBottomStyle: 'solid',
		borderBottomColor: '$rcx-stroke-light',
	},
	without: {},
} as const;

const tabsLayouts = {
	row: {},
	stretch: {
		flexDirection: 'column',
	},
} as const;

const tabsScrollBoxFrame = {
	render: 'div',
	display: 'block',
	flexDirection: 'row',
	alignItems: 'normal',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	position: 'relative',
	overflow: 'auto',
	marginBlock: -4,
} as const;

const tabsWrapperFrame = {
	render: 'div',
	display: 'flex',
	flexDirection: 'row',
	flexWrap: 'nowrap',
	alignItems: 'normal',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	position: 'static',
	marginBlock: 0,
	marginInline: '$space.x12',
	paddingBlock: '$space.x4',
	paddingInline: 0,
} as const;

// end of generated

const TabsFrame = styled(View, {
	...tabsFrame,
	variants: {
		divider: tabsDividers,
		layout: tabsLayouts,
	},
});

const TabsScrollBox = styled(View, tabsScrollBoxFrame);

const TabsWrapper = styled(View, tabsWrapperFrame);

/**
 * Tabs is a component to navigate around the UI using buttons arranged together with the selected tab highlighted.
 */
function Tabs(props: TabsProps) {
	const { children, divider = true, stretch = false } = props;
	return (
		<TabsContext.Provider value={tabsValue(divider, stretch)}>
			<TabsFrame
				divider={divider ? 'with' : 'without'}
				layout={stretch ? 'stretch' : 'row'}
				className={prependClassName(
					props.className,
					`rcx-box rcx-box--full rcx-tabs${stretch ? ' rcx-tabs--stretch' : ''}${divider ? ' rcx-tabs--with-divider' : ''}`,
				)}
				render={
					<div {...ariaAndDataAttributes(props)} {...pickWebPressHandlers(props)} ref={props.ref} id={props.id} title={props.title} />
				}
			>
				<TabsScrollBox className='rcx-box rcx-box--full rcx-tabs__scroll-box'>
					<TabsWrapper className='rcx-box rcx-box--full rcx-tabs__wrapper' render={<div role='tablist' />}>
						{children}
					</TabsWrapper>
				</TabsScrollBox>
			</TabsFrame>
		</TabsContext.Provider>
	);
}

export default Tabs;
